import { Sidebar, type SidebarModeChangeDetail, type SidebarNavigateDetail } from '@absoluteui/components/sidebar';

const host = document.querySelector<HTMLElement>('#app-sidebar');
const menuButton = document.querySelector<HTMLButtonElement>('#app-menu');
if (host && menuButton) {
  const sidebar = Sidebar.create(host, {
    label: 'Main',
    breakpoint: 1024,
    items: [
      { id: 'inbox', label: 'Inbox', href: '/inbox' },
      { id: 'archive', label: 'Archive', href: '/archive' },
      { id: 'settings', label: 'Settings', href: '/settings' },
    ],
    value: 'inbox',
  });
  // The application owns the menu button; it is needed only in drawer mode.
  menuButton.hidden = sidebar.mode === 'inline';
  menuButton.addEventListener('click', () => {
    sidebar.toggle();
  });
  host.addEventListener('aui-mode-change', (event) => {
    menuButton.hidden = (event as CustomEvent<SidebarModeChangeDetail>).detail.mode === 'inline';
  });
  // SPA routing: cancel native navigation, route, then mark the item active and close the drawer.
  host.addEventListener('aui-navigate', (event) => {
    const { id, item } = (event as CustomEvent<SidebarNavigateDetail>).detail;
    if (item.href === undefined) return;
    event.preventDefault();
    history.pushState(null, '', item.href);
    sidebar.select(id);
    sidebar.close();
  });
}

import { Sidebar, type SidebarChangeDetail, type SidebarCollapsedChangeDetail } from '@absoluteui/components/sidebar';

const host = document.querySelector<HTMLElement>('#workspace-nav');
if (host) {
  // The sidebar persists nothing; the application may remember the rail state itself.
  let stored: string | null = null;
  try {
    stored = localStorage.getItem('workspace-nav-collapsed');
  } catch {
    stored = null;
  }
  Sidebar.create(host, {
    label: 'Workspace',
    collapsed: stored === 'true',
    items: [
      { id: 'calendar', label: 'Calendar', icon: 'calendar' },
      { id: 'tasks', label: 'Tasks', icon: 'check' },
      { id: 'activity', label: 'Activity', icon: 'clock' },
    ],
    value: 'calendar',
  });
  host.addEventListener('aui-collapsed-change', (event) => {
    const { collapsed } = (event as CustomEvent<SidebarCollapsedChangeDetail>).detail;
    try {
      localStorage.setItem('workspace-nav-collapsed', String(collapsed));
    } catch {
      // Storage unavailable (private mode, blocked): keep the in-memory state only.
    }
  });
  // Items without href are buttons: switch views in place.
  host.addEventListener('aui-change', (event) => {
    document.body.dataset.view = (event as CustomEvent<SidebarChangeDetail>).detail.value;
  });
}
